SELECT lower(hex(span_id)) AS span FROM tqd_cat.spans AS s WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND ((multiIf(dynamicType(attrs.`a`) != 'None', (coalesce(attrs.`a`.:Int64 = 1, false) OR coalesce(attrs.`a`.:Float64 = 1, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`a`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`a`.:Int64 = 1, false) OR coalesce(attrs.`a`.:Float64 = 1, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`a`), arrayExists(x -> x = 1, events.attrs.`a`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`a`), arrayExists(x -> x = 1, links.attrs.`a`.:Int64), multiIf(dynamicType(scope_attrs.`a`) != 'None', (coalesce(scope_attrs.`a`.:Int64 = 1, false) OR coalesce(scope_attrs.`a`.:Float64 = 1, false)), false)))))) AND (name = 'b')) ORDER BY span FORMAT TSV
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001
